  if (stderr_pipe[1] >= 0) { close(stderr_pipe[1]); _spawn_res.stderr_parent_fd = stderr_pipe[0]; }
  if (stdin_mode == 1) close(stdin_fd);
  if (stdout_mode == 1) close(stdout_fd);
  if (stderr_mode == 1) close(stderr_fd);
